/**
 * The main menu. Each item sits to the left or right of the wordmark.
 *
 * This interface was referenced by `Config`'s JSON-Schema
 * via the `definition` "navigation".
 */
export interface Navigation {
  id: number;
  /**
   * Drag to reorder. Items appear in this order on their side of the logo, so moving one between sides changes where it sits in the header.
   */
  items?:
    | {
        label: string;
        /**
         * A path on this site, e.g. /dresses or /about.
         */
        url: string;
        /**
         * The header splits the menu either side of the wordmark.
         */
        side: 'left' | 'right';
        /**
         * Optional. Adding links here turns the item into a dropdown. Wedding Dresses and Designers fill theirs in from the catalogue automatically, so they need nothing here.
         */
        children?:
          | {
              label: string;
              url: string;
              id?: string | null;
            }[]
          | null;
        id?: string | null;
      }[]
    | null;
  /**
   * The button at the far right of the header.
   */
  appointmentLabel?: string | null;
  /**
   * The address of the portal brides sign in to. Leave empty to hide the portal icon.
   */
  bridalPortalURL?: string | null;
  updatedAt?: string | null;
  createdAt?: string | null;
}
